// Real in-game 3D model asset renders for Cities: Skylines II Bus Stop prefabs
export interface BusStopModelData {
    id: string;
    title: string;
    subtitle: string;
    image: string;
    isCustom?: boolean;
}

export const BUS_STOP_MODELS: Record<string, BusStopModelData> = {
    "All": {
        id: "All",
        title: "All Models (Random)",
        subtitle: "Randomized Mix",
        image: "data:image/jpeg;base64,"
    },
    "EU_BusStop01": {
        id: "EU_BusStop01",
        title: "EU Bus Stop Sign",
        subtitle: "Curbside Pole Sign",
        image: "data:image/jpeg;base64,"
    },
    "EU_BusStop02": {
        id: "EU_BusStop02",
        title: "EU Modern Shelter",
        subtitle: "Curved Glass Shelter",
        image: "data:image/jpeg;base64,"
    },
    "NA_BusStop01": {
        id: "NA_BusStop01",
        title: "NA Bus Stop Sign",
        subtitle: "No Standing Round Sign",
        image: "data:image/jpeg;base64,"
    },
    "NA_BusStop02": {
        id: "NA_BusStop02",
        title: "NA Bus Shelter",
        subtitle: "Cantilever Glass Shelter",
        image: "data:image/jpeg;base64,"
    },
    "EU_BusStopBicycle01": {
        id: "EU_BusStopBicycle01",
        title: "EU Shelter + Bikes",
        subtitle: "Curved Shelter & Bike Hoops",
        image: "data:image/jpeg;base64,"
    },
    "NA_BusStopBicycle01": {
        id: "NA_BusStopBicycle01",
        title: "NA Shelter + Bikes",
        subtitle: "Shelter & Square Bike Racks",
        image: "data:image/jpeg;base64,"
    },
    "Pack7-BusStop01": {
        id: "Pack7-BusStop01",
        title: "Contemporary Shelter",
        subtitle: "Curved Wood Ribbon Canopy",
        image: "data:image/jpeg;base64,"
    },
};

export function getBusStopModelInfo(prefabName: string, fallbackIcon?: string): BusStopModelData {
    if (BUS_STOP_MODELS[prefabName]) {
        return BUS_STOP_MODELS[prefabName];
    }
    // Clean up generic/custom prefab names
    const cleanTitle = prefabName
        .replace(/_/g, ' ')
        .replace(/([a-z])([A-Z])/g, '$1 $2')
        .trim();

    return {
        id: prefabName,
        title: cleanTitle,
        subtitle: 'Custom Mod Stop',
        image: fallbackIcon || 'Media/Game/Icons/BusStop.svg',
        isCustom: true
    };
}
